<?php
require_once __DIR__ . '/includes/auth.php';
require_once __DIR__ . '/includes/db.php';

if (isLoggedIn()) {
    header('Location: ' . (isAdmin() ? 'index.php' : 'portal.php'));
    exit;
}

$error   = '';
$success = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $full_name = sanitize($_POST['full_name'] ?? '');
    $username  = sanitize($_POST['username']  ?? '');
    $email     = sanitize($_POST['email']     ?? '');
    $phone     = sanitize($_POST['phone']     ?? '');
    $dob       = $_POST['date_of_birth'] ?? '';
    $sex       = $_POST['sex'] ?? 'Female';
    $address   = sanitize($_POST['address']  ?? '');
    $password  = $_POST['password']  ?? '';
    $confirm   = $_POST['confirm']   ?? '';

    if (!$full_name || !$username || !$password) {
        $error = 'Full name, username, and password are required.';
    } elseif (strlen($password) < 6) {
        $error = 'Password must be at least 6 characters.';
    } elseif ($password !== $confirm) {
        $error = 'Passwords do not match.';
    } else {
        $db   = getDB();
        $chk  = $db->prepare('SELECT id FROM users WHERE username = ? LIMIT 1');
        $chk->execute([$username]);
        if ($chk->fetch()) {
            $error = 'Username already taken. Please choose another.';
        } else {
            $hash = password_hash($password, PASSWORD_DEFAULT);
            $stmt = $db->prepare('
                INSERT INTO users (username, password_hash, full_name, email, phone, date_of_birth, sex, address, role)
                VALUES (?,?,?,?,?,?,?,?,?)
            ');
            $stmt->execute([$username, $hash, $full_name, $email, $phone, $dob ?: null, $sex, $address, 'patient']);
            $newUserId = (int)$db->lastInsertId();

            // NOTE: The `patients` table is for hospital-admitted patients
            // managed by staff and has no user_id column. Self-registered
            // accounts live only in `users`. Staff will create a patient
            // record separately when the user is admitted.

            $success = 'Account created! You can now <a href="login.php">sign in</a>.';
        }
    }
}
