<script>
  function toggleEye(inputId, btn) {
    var input = document.getElementById(inputId);
    var isHidden = input.type === 'password';
    input.type = isHidden ? 'text' : 'password';
    // Switch icon: open eye vs eye-off
    btn.querySelector('svg').innerHTML = isHidden
      ? '<path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/><path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/><line x1="1" y1="1" x2="23" y2="23" stroke-width="2" stroke-linecap="round"/>'
      : '<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>';
  }

  function checkMatch() {
    var p1  = document.getElementById('pw1').value;
    var p2  = document.getElementById('pw2').value;
    var msg = document.getElementById('pw-match-msg');
    if (!p2) { msg.textContent = ''; return; }
    if (p1 === p2) {
      msg.textContent = '✓ Passwords match';
      msg.className = 'pw-match ok';
    } else {
      msg.textContent = '✗ Passwords do not match';
      msg.className = 'pw-match err';
    }
  }
</script>
